const h = $('T1 Health').first().json;
const w = $('T2 Post Weight').first().json;
const m = $('T3 Post Meal').first().json;
const p = $('T4 Post Plan').first().json;
const l = $('T5 Post Log').first().json;
const d = $('T6 Dashboard').first().json;
const r = $('T7 Weekly Report').first().json;

const tests = [
  { name: 'Health: status=ok', pass: h?.status === 'ok' },
  { name: 'Health: service=GymTracker AI', pass: h?.service === 'GymTracker AI' },
  { name: 'Weight: record created', pass: !!w?.data?.id },
  { name: 'Weight: value=76.5', pass: w?.data?.weight === 76.5 },
  { name: 'Weight: body_fat=17.8', pass: w?.data?.body_fat === 17.8 },
  { name: 'Meal: record created', pass: !!m?.data?.id },
  { name: 'Meal: calories=389', pass: m?.data?.calories === 389 },
  { name: 'Meal: protein=17', pass: m?.data?.protein === 17 },
  { name: 'Plan: record created', pass: !!p?.data?.id },
  { name: 'Plan: exercise stored', pass: p?.data?.exercise === 'MCP Bench Press' },
  { name: 'Log: record created', pass: !!l?.data?.id },
  { name: 'Log: weight=100', pass: l?.data?.weight === 100 },
  { name: 'Log: completed=1', pass: l?.data?.completed === 1 },
  { name: 'Dashboard: has latestWeight', pass: !!d?.data?.latestWeight },
  { name: 'Dashboard: caloriesToday>0', pass: (d?.data?.caloriesToday || 0) > 0 },
  { name: 'Dashboard: weekWorkouts>=1', pass: (d?.data?.weekWorkouts || 0) >= 1 },
  { name: 'Dashboard: weightHistory array', pass: Array.isArray(d?.data?.weightHistory) },
  { name: 'Report: workoutsCompleted>=1', pass: (r?.data?.workoutsCompleted || 0) >= 1 },
  { name: 'Report: avgDailyCalories>0', pass: (r?.data?.avgDailyCalories || 0) > 0 },
  { name: 'Report: weightChange present', pass: !!r?.data?.weightChange },
];

const passed = tests.filter(t => t.pass).length;
const failed = tests.filter(t => !t.pass).length;
const score = Math.round(passed / tests.length * 100);

return [{
  json: {
    suite: 'GymTracker AI — n8n MCP Test Suite',
    timestamp: new Date().toISOString(),
    passed, failed,
    total: tests.length,
    score: score + '%',
    status: score === 100 ? 'ALL PASS 🏆' : 'PARTIAL ⚠️',
    tests
  }
}];
